mapper.select:
SELECT a.article_id, a.title, a.slug, CAST(COUNT(*) AS CHAR) AS page_view_count FROM blog_page_view v JOIN blog_article a ON a.article_id = v.article_id AND a.deleted_at IS NULL WHERE v.site_code = 'blog' AND v.view_time >= #{begin}
AND v.view_time < #{end}
GROUP BY a.article_id, a.title, a.slug ORDER BY COUNT(*) DESC, a.article_id DESC LIMIT #{limit}
